import {properties,problem} from './graph.mjs';
const $=id=>document.getElementById(id),NS='http://www.w3.org/2000/svg';
let n=6,edges=[],positions=[],selected=null,mode='free',round=0,initial=[],drag=null,suppressClick=false;
const labels=['連結である','閉路をもたない','辺の本数が「頂点数 − 1」である','任意の異なる2頂点の間に、ただ1つの道がある','どの辺を1本削除しても非連結になる','存在しない辺をどこに1本追加しても閉路ができる'];
function layout(){positions=Array.from({length:n},(_,i)=>({x:340+215*Math.cos(-Math.PI/2+2*Math.PI*i/n),y:240+174*Math.sin(-Math.PI/2+2*Math.PI*i/n)}));}
function element(tag,attrs){const el=document.createElementNS(NS,tag);for(const [k,v] of Object.entries(attrs))el.setAttribute(k,v);return el;}
function selectVertex(i){if(selected===null){selected=i;}else if(selected===i){selected=null;}else{const pair=[selected,i].sort((a,b)=>a-b);if(!edges.some(([a,b])=>a===pair[0]&&b===pair[1]))edges.push(pair);selected=null;}render();}
function removeEdge(a,b){edges=edges.filter(([u,v])=>u!==a||v!==b);selected=null;render();}
function draw(){const svg=$('graph');svg.replaceChildren();for(const [a,b] of edges){const g=element('g',{class:'edge-group',role:'button',tabindex:0,'aria-label':`辺 ${a+1} と ${b+1} を削除`});for(const cls of ['edge','edge-hit'])g.append(element('line',{class:cls,x1:positions[a].x,y1:positions[a].y,x2:positions[b].x,y2:positions[b].y}));g.addEventListener('click',()=>removeEdge(a,b));g.addEventListener('keydown',e=>{if(['Enter',' ','Delete','Backspace'].includes(e.key)){e.preventDefault();removeEdge(a,b);}});svg.append(g);}
for(let i=0;i<n;i++){const p=positions[i],g=element('g',{class:`vertex${selected===i?' selected':''}`,transform:`translate(${p.x} ${p.y})`,role:'button',tabindex:0,'aria-label':`頂点 ${i+1}`,'aria-pressed':selected===i});g.append(element('circle',{r:25}));const t=element('text',{});t.textContent=i+1;g.append(t);g.addEventListener('pointerdown',e=>{if(e.button!==0)return;e.preventDefault();suppressClick=false;drag={id:e.pointerId,i,x:e.clientX,y:e.clientY,start:{...positions[i]},moved:false};});g.addEventListener('click',e=>{if(!suppressClick)selectVertex(i);suppressClick=false;});g.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();selectVertex(i);$('graph').querySelectorAll('.vertex')[i].focus();}});svg.append(g);}}
function render(){draw();$('n-count').textContent=n;$('e-count').textContent=edges.length;$('selection').textContent=selected===null?'頂点を2つ選んで、辺をつなぐ':`頂点 ${selected+1} を選択中 · もう1つの頂点を選ぶ（同じ頂点で解除）`;
const show=$('show').checked;const p=show?properties(n,edges):null;$('property-list').replaceChildren(...labels.map((label,i)=>{const li=document.createElement('li');const number=document.createElement('span');number.className='number';number.textContent=String(i+1).padStart(2,'0');const txt=document.createElement('span');txt.className='property-text';txt.textContent=label;const mark=document.createElement('span');mark.className=`verdict ${!show?'na':p.values[i]===true?'yes':p.values[i]===null?'na':''}`;mark.textContent=!show?'？':p.values[i]===null?'—':p.values[i]?'○':'×';mark.setAttribute('aria-label',!show?'判定非表示':p.values[i]===null?'追加できる辺なし':p.values[i]?'成立する':'成立しない');li.append(number,txt,mark);return li;}));$('tree').hidden=!show||!p.tree;}
function point(x,y){const p=new DOMPoint(x,y);return p.matrixTransform($('graph').getScreenCTM().inverse());}
$('graph').addEventListener('pointermove',e=>{if(!drag||drag.id!==e.pointerId)return;if(Math.hypot(e.clientX-drag.x,e.clientY-drag.y)>6)drag.moved=true;if(drag.moved){$('graph').setPointerCapture(e.pointerId);const a=point(drag.x,drag.y),b=point(e.clientX,e.clientY);positions[drag.i]={x:Math.max(30,Math.min(650,drag.start.x+b.x-a.x)),y:Math.max(30,Math.min(450,drag.start.y+b.y-a.y))};draw();}});
$('graph').addEventListener('pointerup',e=>{if(!drag||drag.id!==e.pointerId)return;const d=drag;drag=null;if($('graph').hasPointerCapture(e.pointerId))$('graph').releasePointerCapture(e.pointerId);suppressClick=true;if(!d.moved)selectVertex(d.i);});
$('graph').addEventListener('pointercancel',()=>{drag=null;});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){selected=null;render();}});
function start(){selected=null;drag=null;layout();edges=mode==='free'?[]:problem(n,round%4);initial=edges.map(e=>[...e]);$('problem-label').textContent=`問題 ${round+1}`;render();}
function changeMode(value){mode=value;round=0;for(const id of ['free','challenge']){$(id).classList.toggle('active',id===mode);$(id).setAttribute('aria-pressed',id===mode);}$('next').hidden=mode==='free';$('problem-label').hidden=mode==='free';$('canvas-title').textContent=mode==='free'?'自由につないでみよう':'辺を変えて、木にしてみよう';start();}
$('free').onclick=()=>changeMode('free');$('challenge').onclick=()=>changeMode('challenge');$('size').onchange=()=>{n=Number($('size').value);start();};$('show').onchange=render;$('reset').onclick=()=>{selected=null;layout();edges=initial.map(e=>[...e]);render();};$('next').onclick=()=>{round++;start();};
start();
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'edit_graph_edges',description:'表示中のグラフの辺を追加または削除する。頂点番号は1から始まる。',inputSchema:{type:'object',properties:{action:{type:'string',enum:['add','remove']},vertices:{type:'array',items:{type:'integer'},minItems:2,maxItems:2}},required:['action','vertices'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(!input||!['add','remove'].includes(input.action)||!Array.isArray(input.vertices)||input.vertices.length!==2||input.vertices.some(v=>!Number.isInteger(v)||v<1||v>n)||input.vertices[0]===input.vertices[1])throw new Error('有効な異なる頂点番号を2つ指定してください。');const [a,b]=input.vertices.map(v=>v-1).sort((a,b)=>a-b);if(input.action==='remove')removeEdge(a,b);else{if(!edges.some(([u,v])=>u===a&&v===b))edges.push([a,b]);selected=null;render();}return {vertices:n,edges:edges.map(e=>e.map(v=>v+1))};}})).catch(()=>{});}catch{}}
